    99	    public void replaceUsages(Path jspTag, Path jteTag) {
   100	        String oldJspTagPrefix = extractTagPrefix(jspTag);
   101	        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
   102	        String newJteFile = jteRoot.relativize(jteTag).toString().replace('\\', '/');
   103	
   104	        IoUtils.deleteFile(jspTag);
   105	
   106	        try (Stream<Path> stream = Files.walk(jspRoot)) {
   107	            stream
   108	                  .filter(Files::isRegularFile)
   109	                  .filter(p -> !Files.isDirectory(p))
   110	                  .filter(p -> {
   111	                      String fileName = p.toString();
   112	                      return fileName.endsWith(".jsp") || fileName.endsWith(".jsp.inc") || fileName.endsWith(".tag");
   113	                  }).forEach(jspFile -> replaceUsages(jspFile, oldJspTagPrefix, oldJspTagClosing, newJteFile));
   114	        } catch (IOException e) {
   115	            throw new UncheckedIOException(e);
   116	        }
   117	    }
