   122	
   123	    private void replaceUsages(Path jspFile, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
   124	        boolean modified = false;
   125	
   126	        StringBuilder jspContent = new StringBuilder(IoUtils.readFile(jspFile));
   127	
   128	        int lastIndex = 0;
   129	
   130	        do {
   131	            lastIndex = jspContent.indexOf(oldJspTagPrefix, lastIndex);
   132	            if (lastIndex >= 0 && lastIndex < jspContent.length()) {
   133	                char character = jspContent.charAt(lastIndex + oldJspTagPrefix.length());
   134	                if (Character.isWhitespace(character) || character == '/' || character == '>') {
   135	                    jspContent.replace(lastIndex, lastIndex + oldJspTagPrefix.length(), "<" + jteTag + " jte=\"" + newJteFile + "\"");
   136	                    modified = true;
   137	                } else {
   138	                    ++lastIndex;
   139	                }
   140	            } else {
   141	                break;
   142	            }
   143	        } while (true);
   144	
   145	        lastIndex = 0;
   146	
   147	        do {
   148	            lastIndex = jspContent.indexOf(oldJspTagClosing, lastIndex);
   149	            if (lastIndex >= 0 && lastIndex < jspContent.length()) {
   150	                jspContent.replace(lastIndex, lastIndex + oldJspTagClosing.length(), "</" + jteTag + ">");
   151	                modified = true;
   152	            } else {
   153	                break;
   154	            }
   155	        } while (true);
   156	
   157	        if (modified) {
   158	            IoUtils.writeFile(jspFile, jspContent.toString());
   159	        }
   160	    }
   161	
   162	    private String extractTagPrefix(Path jspTag) {
   163	        String fileName = jspTag.getFileName().toString();
   164	        String tagName = fileName.substring(0, fileName.indexOf('.'));
   165	
   166	        String namespace = jspTag.getParent().getFileName().toString();
   167	        if ("tags".equals(namespace)) {
   168	            namespace = "include";
   169	        }
   170	
   171	        return "<" + namespace + ":" + tagName;
   172	    }
   173	
   174	    protected URL getResourceBase() {
   175	        try {
   176	            return Paths.get("").toUri().toURL();
   177	        } catch (MalformedURLException e) {
   178	            throw new UncheckedIOException(e);
   179	        }
   180	    }
   181	
   182	    public String suggestJteFile(String jspFile) {
   183	        int fileSeparatorIndex = jspFile.indexOf('.');
   184	        if (fileSeparatorIndex == -1) {
   185	            throw new IllegalArgumentException("JSP file without file extension " + jspFile);
   186	        }
   187	
   188	        String jspFileWithoutExtension = jspFile.substring(0, fileSeparatorIndex);
   189	
   190	        StringBuilder jteFile = new StringBuilder();
   191	
   192	        jteFile.append(jspFileWithoutExtension);
   193	        CamelCaseConverter.convertTo(jteFile);
   194	        jteFile.append(".jte");
   195	
   196	        return jteFile.toString();
   197	    }
   198	
   199	    protected void checkDependencies(String jteCode) {
   200	        List<String> unresolvedJspTags = findUnresolvedJspTags(jteCode);
   201	        if (unresolvedJspTags.isEmpty()) {
   202	            return;
   203	        }
   204	
   205	        Set<String> notConvertedTagsSet = getNotConvertedTagsAsSet();
   206	
   207	        Set<String> errors = new LinkedHashSet<>();
   208	        for (String unresolvedJspTag : unresolvedJspTags) {
   209	            if (!notConvertedTagsSet.contains(unresolvedJspTag)) {
   210	                errors.add("The tag " + unresolvedJspTag + "/> is used by this tag and not converted to jte yet. You should convert " + unresolvedJspTag + "/> first. If this is a tag that should be always converted by hand, implement getNotConvertedTags() and add it there.");
   211	            }
   212	        }
   213	
   214	        if (!errors.isEmpty()) {
   215	            throw new UnsupportedOperationException(String.join("\n", errors));
   216	        }
   217	    }
   218	
   219	    private Set<String> getNotConvertedTagsAsSet() {
   220	        String[] notConvertedTags = getNotConvertedTags();
   221	        Set<String> notConvertedTagsSet = new HashSet<>();
   222	        if (notConvertedTags != null) {
   223	            for (String notConvertedTag : notConvertedTags) {
   224	                notConvertedTagsSet.add("<" + notConvertedTag);
   225	            }
   226	        }
   227	        return notConvertedTagsSet;
   228	    }
   229	
   230	    protected List<String> findUnresolvedJspTags(String jteCode) {
   231	        List<String> result = new ArrayList<>();
   232	
   233	        Matcher matcher = UNCONVERTED_TAG_REFERENCES.matcher(jteCode);
   234	
   235	        while (matcher.find()) {
   236	            result.add(matcher.group());
   237	        }
   238	
   239	        return result;
   240	    }
